// Rebuild after changing the pet PNG. Inline data avoids local WXSS URL restrictions.
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const config = require('../config/pet');
const mask = 'url("data:image/png;base64,' + fs.readFileSync(path.join(root, config.image)).toString('base64') + '")';
fs.writeFileSync(path.join(root, 'utils/pet-rainbow.wxss'),
  '/* Generated by node tests/generate-pet-mask.js */\n.pet-rainbow { -webkit-mask-image: ' + mask + '; mask-image: ' + mask + '; }\n');
